template <typename T>
class Register {
private:
    T prev;
    T next;
    bool _stall;

public:
    Register()
        : prev(0), next(0), _stall(false) {}

    Register(T d)
        : prev(d), next(d), _stall(false) {}

    T read() const {
        return prev;
    }

    T current() const {
        return next;
    }

    void write(const T &t) {
        next = t;
    }

    void tick() {
        if (!_stall) prev = next;
    }

    void stall(bool stall) {
        _stall = stall;
    }

    operator T() const {
        return read();
    }

    void operator=(T next_val) {
        write(next_val);
    }
};
